import{_ as n,a0 as d,w as l,s as r,I as a,x as e,a1 as i,A as t,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Podman：一个更安全的运行容器的方式 | LCTT x X-CMD","titleTemplate":false,"description":"Podman：一个更安全的运行容器的方式 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Podman：一个更安全的运行容器的方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Podman：一个更安全的运行容器的方式 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20181030 Podman- A more secure way to run containers","title":"Podman：一个更安全的运行容器的方式","tag":"201908","desc":""},"relativePath":"201908/20181030 Podman- A more secure way to run containers.md","filePath":"[post].md"}'),c={name:"201908/20181030 Podman- A more secure way to run containers.md"};function u(h,s,g,k,f,m){const o=d("Link");return l(),r("div",null,[s[18]||(s[18]=a("h1",{id:"podman-一个更安全的运行容器的方式",tabindex:"-1"},[e("Podman：一个更安全的运行容器的方式 "),a("a",{class:"header-anchor",href:"#podman-一个更安全的运行容器的方式","aria-label":"Permalink to “Podman：一个更安全的运行容器的方式”"},"​")],-1)),s[19]||(s[19]=a("blockquote",null,[a("p",null,"Podman 使用传统的 fork/exec 模型（相对于客户端/服务器模型）来运行容器。")],-1)),s[20]||(s[20]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/201908/23/234924m55sn8zt3b5q8815.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在进入本文的主要主题 ",-1)),i(o,{href:"https://podman.io"},{default:t(()=>[...s[0]||(s[0]=[e("Podman",-1)])]),_:1}),s[2]||(s[2]=e(" 和容器之前，我需要了解一点 Linux 审计功能的技术。",-1))]),s[21]||(s[21]=p(`<h3 id="什么是审计" tabindex="-1">什么是审计？ <a class="header-anchor" href="#什么是审计" aria-label="Permalink to “什么是审计？”">​</a></h3><p>Linux 内核有一个有趣的安全功能，叫做<strong>审计</strong>。它允许管理员在系统上监视安全事件，并将它们记录到<code>audit.log</code> 中，该文件可以本地存储或远程存储在另一台机器上，以防止黑客试图掩盖他的踪迹。</p><p><code>/etc/shadow</code> 文件是一个经常要监控的安全文件，因为向其添加记录可能允许攻击者获得对系统的访问权限。管理员想知道是否有任何进程修改了该文件，你可以通过执行以下命令来执行此操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># auditctl -w /etc/shadow</span></span></code></pre></div><p>现在让我们看看当我修改了 <code>/etc/shadow</code> 文件会发生什么：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># touch /etc/shadow </span></span>
<span class="line"><span># ausearch -f /etc/shadow -i -ts recent</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type=PROCTITLE msg=audit(10/10/2018 09:46:03.042:4108) : proctitle=touch /etc/shadow type=SYSCALL msg=audit(10/10/2018 09:46:03.042:4108) : arch=x86_64 syscall=openat success=yes exit=3 a0=0xffffff9c a1=0x7ffdb17f6704 a2=O_WRONLY|O_CREAT|O_NOCTTY| O_NONBLOCK a3=0x1b6 items=2 ppid=2712 pid=3727 auid=dwalsh uid=root gid=root euid=root suid=root fsuid=root egid=root sgid=root fsgid=root tty=pts1 ses=3 comm=touch exe=/usr/bin/touch subj=unconfined_u:unconfined_r:unconfined_t:s0-s0:c0.c1023 key=(null)\`</span></span></code></pre></div><p>审计记录中有很多信息，但我重点注意到它记录了 root 修改了 <code>/etc/shadow</code> 文件，并且该进程的审计 UID（<code>auid</code>）的所有者是 <code>dwalsh</code>。</p><p>内核修改了这个文件了么？</p><h4 id="跟踪登录-uid" tabindex="-1">跟踪登录 UID <a class="header-anchor" href="#跟踪登录-uid" aria-label="Permalink to “跟踪登录 UID”">​</a></h4><p>登录 UID（<code>loginuid</code>），存储在 <code>/proc/self/loginuid</code> 中，它是系统上每个进程的 proc 结构的一部分。该字段只能设置一次；设置后，内核将不允许任何进程重置它。</p><p>当我登录系统时，登录程序会为我的登录过程设置 <code>loginuid</code> 字段。</p><p>我（<code>dwalsh</code>）的 UID 是 3267。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/self/loginuid</span></span>
<span class="line"><span>3267</span></span></code></pre></div><p>现在，即使我变成了 root，我的登录 UID 仍将保持不变。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cat /proc/self/loginuid</span></span>
<span class="line"><span>3267</span></span></code></pre></div><p>请注意，从初始登录过程 fork 并 exec 的每个进程都会自动继承 <code>loginuid</code>。这就是内核知道登录的人是 <code>dwalsh</code> 的方式。</p><h3 id="容器" tabindex="-1">容器 <a class="header-anchor" href="#容器" aria-label="Permalink to “容器”">​</a></h3><p>现在让我们来看看容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo podman run fedora cat /proc/self/loginuid</span></span>
<span class="line"><span>3267</span></span></code></pre></div><p>甚至容器进程也保留了我的 <code>loginuid</code>。 现在让我们用 Docker 试试。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo docker run fedora cat /proc/self/loginuid </span></span>
<span class="line"><span>4294967295</span></span></code></pre></div><h3 id="为什么不一样" tabindex="-1">为什么不一样？ <a class="header-anchor" href="#为什么不一样" aria-label="Permalink to “为什么不一样？”">​</a></h3><p>Podman 对于容器使用传统的 fork/exec 模型，因此容器进程是 Podman 进程的后代。Docker 使用客户端/服务器模型。我执行的 <code>docker</code> 命令是 Docker 客户端工具，它通过客户端/服务器操作与 Docker 守护进程通信。然后 Docker 守护程序创建容器并处理 stdin/stdout 与 Docker 客户端工具的通信。</p><p>进程的默认 <code>loginuid</code>（在设置 <code>loginuid</code> 之前）是 <code>4294967295</code>（LCTT 译注：2^32 - 1）。由于容器是 Docker 守护程序的后代，而 Docker 守护程序是 init 系统的子代，所以，我们看到 systemd、Docker 守护程序和容器进程全部具有相同的 <code>loginuid</code>：<code>4294967295</code>，审计系统视其为未设置审计 UID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /proc/1/loginuid </span></span>
<span class="line"><span>4294967295</span></span></code></pre></div><h3 id="怎么会被滥用" tabindex="-1">怎么会被滥用？ <a class="header-anchor" href="#怎么会被滥用" aria-label="Permalink to “怎么会被滥用？”">​</a></h3><p>让我们来看看如果 Docker 启动的容器进程修改 <code>/etc/shadow</code> 文件会发生什么。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run --privileged -v /:/host fedora touch /host/etc/shadow </span></span>
<span class="line"><span>$ sudo ausearch -f /etc/shadow -i type=PROCTITLE msg=audit(10/10/2018 10:27:20.055:4569) : proctitle=/usr/bin/coreutils --coreutils-prog-shebang=touch /usr/bin/touch /host/etc/shadow type=SYSCALL msg=audit(10/10/2018 10:27:20.055:4569) : arch=x86_64 syscall=openat success=yes exit=3 a0=0xffffff9c a1=0x7ffdb6973f50 a2=O_WRONLY|O_CREAT|O_NOCTTY| O_NONBLOCK a3=0x1b6 items=2 ppid=11863 pid=11882 auid=unset uid=root gid=root euid=root suid=root fsuid=root egid=root sgid=root fsgid=root tty=(none) ses=unset comm=touch exe=/usr/bin/coreutils subj=system_u:system_r:spc_t:s0 key=(null)</span></span></code></pre></div><p>在 Docker 情形中，<code>auid</code> 是未设置的（<code>4294967295</code>）；这意味着安全人员可能知道有进程修改了 <code>/etc/shadow</code> 文件但身份丢失了。</p><p>如果该攻击者随后删除了 Docker 容器，那么在系统上谁修改 <code>/etc/shadow</code> 文件将没有任何跟踪信息。</p><p>现在让我们看看相同的场景在 Podman 下的情况。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo podman run --privileged -v /:/host fedora touch /host/etc/shadow </span></span>
<span class="line"><span>$ sudo ausearch -f /etc/shadow -i type=PROCTITLE msg=audit(10/10/2018 10:23:41.659:4530) : proctitle=/usr/bin/coreutils --coreutils-prog-shebang=touch /usr/bin/touch /host/etc/shadow type=SYSCALL msg=audit(10/10/2018 10:23:41.659:4530) : arch=x86_64 syscall=openat success=yes exit=3 a0=0xffffff9c a1=0x7fffdffd0f34 a2=O_WRONLY|O_CREAT|O_NOCTTY| O_NONBLOCK a3=0x1b6 items=2 ppid=11671 pid=11683 auid=dwalsh uid=root gid=root euid=root suid=root fsuid=root egid=root sgid=root fsgid=root tty=(none) ses=3 comm=touch exe=/usr/bin/coreutils subj=unconfined_u:system_r:spc_t:s0 key=(null)</span></span></code></pre></div><p>由于它使用传统的 fork/exec 方式，因此 Podman 正确记录了所有内容。</p><p>这只是观察 <code>/etc/shadow</code> 文件的一个简单示例，但审计系统对于观察系统上的进程非常有用。使用 fork/exec 容器运行时（而不是客户端/服务器容器运行时）来启动容器允许你通过审计日志记录保持更好的安全性。</p><h3 id="最后的想法" tabindex="-1">最后的想法 <a class="header-anchor" href="#最后的想法" aria-label="Permalink to “最后的想法”">​</a></h3><p>在启动容器时，与客户端/服务器模型相比，fork/exec 模型还有许多其他不错的功能。例如，systemd 功能包括：</p><ul><li><code>SD_NOTIFY</code>：如果将 Podman 命令放入 systemd 单元文件中，容器进程可以通过 Podman 返回通知，表明服务已准备好接收任务。这是在客户端/服务器模式下无法完成的事情。</li><li>套接字激活：你可以将连接的套接字从 systemd 传递到 Podman，并传递到容器进程以便使用它们。这在客户端/服务器模型中是不可能的。</li></ul><p>在我看来，其最好的功能是<strong>作为非 root 用户运行 Podman 和容器</strong>。这意味着你永远不会在宿主机上授予用户 root 权限，而在客户端/服务器模型中（如 Docker 使用的），你必须打开以 root 身份运行的特权守护程序的套接字来启动容器。在那里，你将受到守护程序中实现的安全机制与宿主机操作系统中实现的安全机制的支配 —— 这是一个危险的主张。</p><hr>`,39)),a("p",null,[s[4]||(s[4]=e("via: ",-1)),i(o,{href:"https://opensource.com/article/18/10/podman-more-secure-way-run-containers"},{default:t(()=>[...s[3]||(s[3]=[e("https://opensource.com/article/18/10/podman-more-secure-way-run-containers",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=e("作者：",-1)),i(o,{href:"https://opensource.com/users/rhatdan"},{default:t(()=>[...s[5]||(s[5]=[e("Daniel J Walsh",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),i(o,{href:"https://github.com/wxy"},{default:t(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=e("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),i(o,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const C=n(c,[["render",u]]);export{x as __pageData,C as default};
